selector_to_html = {"a[href=\"#console\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Console<a class=\"headerlink\" href=\"#console\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#close-a-trace\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Close a trace<a class=\"headerlink\" href=\"#close-a-trace\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#typical-investigation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Typical investigation<a class=\"headerlink\" href=\"#typical-investigation\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#errors\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Errors<a class=\"headerlink\" href=\"#errors\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#request-details\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Request details<a class=\"headerlink\" href=\"#request-details\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#snapshots\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Snapshots<a class=\"headerlink\" href=\"#snapshots\" title=\"Link to this heading\">#</a></h3><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">snapshot</span></code> command loads the DOM snapshot for an action into a headless browser and runs a single browser command against it. Without a browser command, it returns the accessibility snapshot.</p>", "a[href=\"#open-a-trace\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Open a trace<a class=\"headerlink\" href=\"#open-a-trace\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#actions\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Actions<a class=\"headerlink\" href=\"#actions\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#action-details\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Action details<a class=\"headerlink\" href=\"#action-details\" title=\"Link to this heading\">#</a></h3><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">action</span></code> command displays available snapshot phases (before, input, after) and the exact command to extract them.</p>", "a[href=\"#commands\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Commands<a class=\"headerlink\" href=\"#commands\" title=\"Link to this heading\">#</a></h2><h3>Open a trace<a class=\"headerlink\" href=\"#open-a-trace\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#workflow\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Workflow<a class=\"headerlink\" href=\"#workflow\" title=\"Link to this heading\">#</a></h2><p>All commands after <code class=\"docutils literal notranslate\"><span class=\"pre\">open</span></code> operate on the currently opened trace \u2014 no need to pass the trace file again. Opening a new trace replaces the previous one.</p>", "a[href=\"#playwright-trace-cli\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Playwright Trace CLI<a class=\"headerlink\" href=\"#playwright-trace-cli\" title=\"Link to this heading\">#</a></h1><p>Inspect <code class=\"docutils literal notranslate\"><span class=\"pre\">.zip</span></code> trace files produced by Playwright tests without opening a browser.</p>", "a[href=\"#requests\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Requests<a class=\"headerlink\" href=\"#requests\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#attachments\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Attachments<a class=\"headerlink\" href=\"#attachments\" title=\"Link to this heading\">#</a></h3>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
